import os
from datetime import datetime, timedelta, timezone
from typing import Any, Dict, List, Optional

import boto3
from boto3.session import Session
from botocore.exceptions import BotoCoreError, ClientError


def _parse_utc_datetime(value: Any) -> datetime:
    if isinstance(value, datetime):
        return value.astimezone(timezone.utc) if value.tzinfo else value.replace(tzinfo=timezone.utc)
    if isinstance(value, (int, float)):
        return datetime.fromtimestamp(value, tz=timezone.utc)
    if isinstance(value, str):
        s = value.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        dt = datetime.fromisoformat(s)
        return dt.astimezone(timezone.utc) if dt.tzinfo else dt.replace(tzinfo=timezone.utc)
    raise TypeError(f"Unsupported datetime value: {type(value)!r}")


def _period_seconds(start_time: datetime, end_time: datetime, max_datapoints: int = 1440) -> int:
    total_seconds = max(1, int((end_time - start_time).total_seconds()))
    raw = max(60, total_seconds // max(1, max_datapoints))
    return max(60, (raw // 60) * 60 or 60)


def get_aggregated_metric_statistics(
    metric_name: str,
    namespace: str,
    start_time: Any,
    end_time: Any,
    dimensions: Optional[Dict[str, str]] = None,
    statistics: Optional[List[str]] = None,
    period: Optional[int] = None,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Retrieve aggregated CloudWatch metric statistics over a time window.

    Returns a normalized dictionary containing timestamped datapoints and summary aggregates.
    """
    start_dt = _parse_utc_datetime(start_time)
    end_dt = _parse_utc_datetime(end_time)
    if end_dt <= start_dt:
        raise ValueError("end_time must be greater than start_time")

    if statistics is None:
        statistics = ["Average", "Sum", "Minimum", "Maximum"]

    if period is None:
        period = _period_seconds(start_dt, end_dt)

    metric_dimensions = [{"Name": k, "Value": v} for k, v in (dimensions or {}).items()]

    session_kwargs: Dict[str, Any] = {}
    if region_name:
        session_kwargs["region_name"] = region_name
    session: Session = boto3.Session(**session_kwargs)
    cw = session.client("cloudwatch")

    try:
        resp = cw.get_metric_statistics(
            Namespace=namespace,
            MetricName=metric_name,
            Dimensions=metric_dimensions,
            StartTime=start_dt,
            EndTime=end_dt,
            Period=period,
            Statistics=statistics,
        )
    except (ClientError, BotoCoreError) as e:
        raise RuntimeError(f"CloudWatch get_metric_statistics failed: {e}") from e

    datapoints = resp.get("Datapoints", [])
    datapoints.sort(key=lambda x: x.get("Timestamp"))

    normalized_datapoints: List[Dict[str, Any]] = []
    aggregates: Dict[str, Dict[str, Optional[float]]] = {}

    for stat in statistics:
        values = [dp.get(stat) for dp in datapoints if dp.get(stat) is not None]
        aggregates[stat] = {
            "min": min(values) if values else None,
            "max": max(values) if values else None,
            "sum": float(sum(values)) if values else None,
            "avg": (float(sum(values)) / len(values)) if values else None,
        }

    for dp in datapoints:
        normalized_datapoints.append(
            {
                "timestamp": dp.get("Timestamp").astimezone(timezone.utc).isoformat() if dp.get("Timestamp") else None,
                "sample_count": dp.get("SampleCount"),
                "average": dp.get("Average"),
                "sum": dp.get("Sum"),
                "minimum": dp.get("Minimum"),
                "maximum": dp.get("Maximum"),
                "unit": dp.get("Unit"),
            }
        )

    return {
        "provider": "aws_cloudwatch",
        "namespace": namespace,
        "metric_name": metric_name,
        "dimensions": dimensions or {},
        "start_time": start_dt.isoformat(),
        "end_time": end_dt.isoformat(),
        "period": period,
        "statistics": statistics,
        "datapoints": normalized_datapoints,
        "aggregates": aggregates,
        "label": resp.get("Label"),
    }
